package dev.eugheist.ttmodern;
final class BedrockPortalAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT bedrock portal: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var world=server.overworld();var bedrock=server.getLevel(BedrockPortal.DIMENSION);var p=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"PortalAudit"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setPos(25.5,6,25.5);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(AwakenedPick.ITEM.get()));var low=new net.minecraft.core.BlockPos(25,4,25);var high=low.above();var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();saved.put(low,world.getBlockState(low));saved.put(high,world.getBlockState(high));var chamber=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();for(int y=250;y<=255;y++){var pos=new net.minecraft.core.BlockPos(low.getX(),y,low.getZ());chamber.put(pos,bedrock.getBlockState(pos));bedrock.setBlock(pos,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState(),2);}int config=TinkererConfig.BEDROCK_DIMENSION_ID.get();
 try{world.setBlock(low,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState(),2);world.setBlock(high,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState(),2);check(!BedrockPortal.open(p,high)&&world.getBlockState(high).is(net.minecraft.world.level.block.Blocks.BEDROCK),"surface y5 stays bedrock");var denied=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock(p,low,net.minecraft.core.Direction.UP,net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock.Action.START);denied.setCanceled(true);BedrockPortal.click(denied);check(world.getBlockState(low).is(net.minecraft.world.level.block.Blocks.BEDROCK),"canceled native event opens no portal");TinkererConfig.BEDROCK_DIMENSION_ID.set(0);check(!BedrockPortal.open(p,low),"legacy config zero disables portal access");TinkererConfig.BEDROCK_DIMENSION_ID.set(config);
 var click=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock(p,low,net.minecraft.core.Direction.UP,net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock.Action.START);p.setPos(100,6,100);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(click);check(world.getBlockState(low).is(net.minecraft.world.level.block.Blocks.BEDROCK),"out-of-reach native event cannot open portal before vanilla distance check");p.setPos(25.5,6,25.5);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(click);check(world.getBlockState(low).is(BedrockPortal.BLOCK.get()),"real event bus left click opens surface y4");check(BedrockPortal.BLOCK.get().defaultBlockState().getCollisionShape(world,low).isEmpty()&&BedrockPortal.BLOCK.get().asItem()==net.minecraft.world.item.Items.AIR,"original collisionless portal has no item");
 BedrockPortal.chamber(bedrock,low);for(int y=250;y<=253;y++)check(bedrock.getBlockState(new net.minecraft.core.BlockPos(25,y,25)).isAir(),"original destination chamber y"+y);check(bedrock.getBlockState(new net.minecraft.core.BlockPos(25,254,25)).is(BedrockPortal.BLOCK.get())&&bedrock.getBlockState(new net.minecraft.core.BlockPos(25,255,25)).is(net.minecraft.world.level.block.Blocks.BEDROCK),"portal at254 and intact255 roof");
 var guarded=new net.minecraft.core.BlockPos(25,250,25);bedrock.setBlock(guarded,net.minecraft.world.level.block.Blocks.DIAMOND_ORE.defaultBlockState(),2);BedrockPortal.chamber(bedrock,low);check(bedrock.getBlockState(guarded).is(net.minecraft.world.level.block.Blocks.DIAMOND_ORE),"chamber preserves non-bedrock ore quirk");
 var inside=new net.neoforged.neoforge.common.util.FakePlayer(bedrock,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"PortalInsideAudit"));inside.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);bedrock.setBlock(guarded,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState(),2);check(BedrockPortal.open(inside,guarded)&&bedrock.getBlockState(guarded).isAir(),"inside bedrock<=253 removes without drops");
 var cow=net.minecraft.world.entity.EntityType.COW.create(world);cow.setPos(low.getX()+.5,low.getY()+.25,low.getZ()+.5);cow.setNoAi(true);cow.setNoGravity(true);world.addFreshEntity(cow);try{BedrockPortal.BLOCK.get().entityInside(world.getBlockState(low),world,low,cow);check(cow.level()==world&&!cow.isRemoved(),"original block collision ignores nonplayer entities");}finally{cow.discard();}
 var result=BedrockPortal.BLOCK.get().useWithoutItem(world.getBlockState(low),world,low,p,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(low),net.minecraft.core.Direction.UP,low,false));check(result==net.minecraft.world.InteractionResult.PASS&&world.getBlockState(low).is(net.minecraft.world.level.block.Blocks.BEDROCK),"right click closes to bedrock");
 System.out.println("TT BEDROCK PORTAL AUDIT: ALL PASS (native left-click bus/cancellation/config0/surface height,collision/no item,chamber/roof/ore conservation,interior excavation,nonplayer collision retained,right-click closure)");
 }finally{TinkererConfig.BEDROCK_DIMENSION_ID.set(config);saved.forEach((pos,state)->world.setBlock(pos,state,2));chamber.forEach((pos,state)->bedrock.setBlock(pos,state,2));p.discard();}
 }
}
